<?php declare(strict_types=1); /** @var Closure(mixed): string $escape */ $allUnits=$unit['id']===null;$labels=['pending'=>'Pendente','completed'=>'Concluído','cancelled'=>'Cancelado']; ?>
<div class="actions"><div><span class="status">CRM · <?= $escape($unit['name']) ?></span><h1>Follow-ups</h1><p class="meta">Agenda e histórico de acompanhamento dos contatos.</p></div></div>
<?php if($message):?><p class="alert alert-success"><?= $escape($message) ?></p><?php endif;?><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?>
<form method="get" action="<?= $escape($basePath) ?>/crm/follow-ups" class="contact-filters"><select class="form-select" name="status"><option value="">Todas as situações</option><?php foreach($labels as $value=>$label):?><option value="<?= $escape($value) ?>" <?= $selectedStatus===$value?'selected':'' ?>><?= $escape($label) ?></option><?php endforeach;?></select><button type="submit">Filtrar</button></form>
<div class="table-responsive"><table><thead><tr><th>Data/Hora</th><th>Contato</th><?php if($allUnits):?><th>Unidade</th><?php endif;?><th>Próxima ação</th><th>Atendente</th><th>Situação</th><th>Observações</th><th></th></tr></thead><tbody><?php if($followUps===[]):?><tr><td colspan="<?= $allUnits?'8':'7' ?>">Nenhum follow-up encontrado.</td></tr><?php endif;?><?php foreach($followUps as $item):?><tr><td><?= $escape(date('d/m/Y H:i',strtotime((string)$item['scheduled_at']))) ?></td><td><strong><?= $escape($item['contact_name']) ?></strong></td><?php if($allUnits):?><td><?= $escape($item['unit_name']) ?></td><?php endif;?><td><?= $escape($item['action']) ?></td><td><?= $escape($item['responsible_name']) ?></td><td><span class="followup-status followup-<?= $escape($item['status']) ?>"><?= $escape($labels[$item['status']]??$item['status']) ?></span></td><td><?= nl2br($escape($item['notes'])) ?></td><td><?php if(!$allUnits):?><form method="post" action="<?= $escape($basePath) ?>/crm/follow-ups/<?= $escape($item['id']) ?>/status"><?= $csrfField ?><select class="form-select form-select-sm" name="status"><?php foreach($labels as $value=>$label):?><option value="<?= $escape($value) ?>" <?= $item['status']===$value?'selected':'' ?>><?= $escape($label) ?></option><?php endforeach;?></select><button class="btn btn-sm btn-success" type="submit">Aplicar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
